def gen(rng):
    def fmt(office, home, cust):
        lines = [str(len(cust)), f"{office[0]} {office[1]}", f"{home[0]} {home[1]}"]
        lines += [f"{x} {y}" for x, y in cust]
        return "\n".join(lines)

    def rp(lo=0, hi=100):
        return (rng.randint(lo, hi), rng.randint(lo, hi))

    tests = [
        fmt((0, 0), (10, 10), [(5, 0), (10, 5)]),
        fmt((0, 0), (4, 4), [(2, 7)]),
        fmt((0, 0), (0, 0), [(0, 2), (3, 2), (3, 0)]),
        fmt((5, 5), (5, 5), [(5, 5)]),
        fmt((0, 0), (100, 100), [(50, 50)] * 3),
        fmt((0, 0), (100, 0), [(100, 100), (0, 100), (50, 0), (50, 100)]),
        fmt((0, 0), (0, 0), [(100, 100)]),
    ]
    for n in (1, 2, 3, 4, 5, 6, 7, 8):
        for _ in range(4):
            hi = rng.choice([5, 20, 100])
            tests.append(fmt(rp(0, hi), rp(0, hi), [rp(0, hi) for _ in range(n)]))
    # larger N: not brute-checked in time, still must satisfy limits
    for _ in range(3):
        tests.append(fmt(rp(), rp(), [rp() for _ in range(9)]))
    # max-size
    for _ in range(2):
        tests.append(fmt(rp(), rp(), [rp() for _ in range(12)]))
    tests.append(fmt((0, 0), (100, 100), [(rng.randint(0, 100), rng.randint(0, 100)) for _ in range(11)] + [(100, 0)]))
    tests.append(fmt((0, 0), (0, 0), [(i * 8, (i * 37) % 101) for i in range(12)]))
    tests.append(fmt((50, 50), (50, 50), [(rng.choice([0, 100]), rng.choice([0, 100])) for _ in range(12)]))
    return tests

